from pathlib import Path
import json
p=Path(__file__).resolve().parent
spec=json.loads((p/'overview.skeleton.json').read_text())
spec['brief']={'title':'Canada test pack — review overview','reader':'LawScape owner and collaborating Canadian practitioner','action':'Inspect all 30 exercises, record proposed edits and decide what requires revision before release.','purpose':'status','message':'The local test includes 25 questions and five emails; practitioner validation remains pending.','spine':'comparison','situation':'meeting','form':'one-page','sources':[{'id':'PACK','label':'Canada pilot pack.json and local integration','status':'supplied-unverified'}],'assumptions':['The user requested local game integration and the existing LawScape palette.','All people and records are original fictional examples.'],'gaps':['Canadian practitioner legal approval has not been obtained.','No French-language course, new maps, or continuing-matter engine is supplied in this pilot.']}
spec['style']={'source':'design-md','ref':'DESIGN.md'}
texts={
 'context':'The pilot adds original fictional exercises for Ontario, British Columbia and Saskatchewan to local LawScape.',
 'question':'What should the Canadian practitioner review before a wider release?',
 'answer':'All 25 proposed answer keys and five email rubrics. Source retrieval supports review; it does not constitute legal approval.',
 'coverage':'Five questions and one email cover each topic: Ontario representation, BC referrals, BC recording, Saskatchewan language rights, and BC commitments.',
 'scope':'English-language pilot. No AI grading or real email. Canadian test answers do not change Ethics, gold or question tiers. Continuing matters and new maps remain future work.',
 'action':'Open review.html to inspect every option, source and sample reply. Mark proposed ready, revise or hold; export notes as Markdown or JSON. In LawScape, select Canada · TEST PACK.'}
spec['claims']=[{'id':'C-'+id,'text':text,'kind':'material','sourceIds':['PACK'],'placement':'surface','evidenceIds':['pack-detail']} for id,text in texts.items()]
spec['evidence']=[{'id':'pack-detail','cite':'Canada pilot version canada-0.1.0-review','locator':'pack.json: questions, emails, sources and limits; local integration modules','status':'supplied-unverified','sourceId':'PACK','claimRefs':['C-'+id for id in texts],'detail':'Original synthetic curriculum and local test functionality. No practitioner has approved the answer key. Source-byte receipts establish file integrity only.','original':{'availability':'unavailable','label':'Local source: pack.json and README.md in this package; no public release URL.'},'popup':{'type':'detail','title':'What the review package contains','lede':'Thirty original exercises, with a separate record of proposed reviewer decisions.','sections':[{'heading':'Inspect the complete content','body':'review.html shows every question, all four option explanations, five email prompts, fictional records, sample replies and human-review rubrics. QUESTIONS.md and EMAILS.md provide editable text copies. pack.json is the canonical curriculum source.'},{'heading':'Trace the authorities','body':'SOURCES.md identifies five official primary sources, retrieval dates and version limitations. Each exercise cites rule locators. The local originals and hashes are retained in sources/. The LSO Rule 3 page was inaccessible and is not an authority for this pack.'},{'heading':'Record a qualified decision','body':'The review page saves per-exercise decisions and notes in this browser and exports them as Markdown or JSON. Proposed ready is not release approval. The current pack remains unreviewed until the practitioner’s changes and legal sign-off are recorded.'}]}}]
def unit(id,html,role='summary',kind='text',claim=None,detail=False):
 u={'id':id,'kind':kind,'role':role,'claim':claim or texts.get(id,'Canada test pack — review overview'),'claimRefs':['C-'+id] if id in texts else ['C-context'],'relationship':'comparison','candidates':['open narrative','aligned table'],'placeholder':'Describe the review package and its scope.','variants':{'a':{'html':html,'axis':'form','why':'Keep scope, quantities and required review visible.','encoding':'Reading order moves from scope to coverage to review action; table rows compare the five topics.'}}}
 u['evidence']=['pack-detail']
 if detail or kind=='card':u['detail']='pack-detail'
 return u
spec['units']=[unit('title','<h1>Canada test pack — review overview</h1>','title'),unit('context','<p>'+texts['context']+'</p>'),unit('question','<h2>Review question</h2><p>'+texts['question']+'</p>','finding','card'),unit('answer','<h2>Ready for practitioner review</h2><p>'+texts['answer']+'</p>','answer','card'),unit('coverage','<table><thead><tr><th scope="col">Topic and provincial setting</th><th scope="col">Questions</th><th scope="col">Email assignment</th></tr></thead><tbody><tr><td>Ontario · LTB representation</td><td>5</td><td>Assign tomorrow’s hearing</td></tr><tr><td>BC · referrals</td><td>5</td><td>Explain the fee and seek instructions</td></tr><tr><td>BC · recording</td><td>5</td><td>Respond to a preference for notes</td></tr><tr><td>Saskatchewan · language rights</td><td>5</td><td>Implement French-language instructions</td></tr><tr><td>BC · commitments</td><td>5</td><td>Handle an early-release request</td></tr></tbody></table>','summary','table',detail=True),unit('scope','<h2>Test boundaries</h2><p>'+texts['scope']+'</p>','scope','card'),unit('action','<h2>Your next step</h2><p>'+texts['action']+'</p>','action','card',detail=True)]
positions=[('title',1,1,12),('context',2,1,12),('question',3,1,5),('answer',3,6,7),('coverage',4,1,12),('scope',5,1,6),('action',5,7,6)]
spec['composition']={'strategy':'composed','shape':'Review brief with a five-row curriculum table','rationale':'The equal five-question allocation and distinct email topics are most accurately compared in a table. Open narrative gives scope; two final cards distinguish limits and action. No spatial map suggests legal coverage outside the three provinces.','sections':[{'id':'overview','purpose':'Explain the completed test content and pending practitioner review.','unitIds':[x[0] for x in positions],'layout':{'columns':12,'placements':[{'unitId':id,'row':row,'column':col,'span':span} for id,row,col,span in positions]}}],'templateRef':None}
spec['overview']={'sectionId':'overview','contextUnitIds':['context'],'questionUnitId':'question','answerUnitId':'answer','topics':[]}
(p/'overview.plan.json').write_text(json.dumps(spec,indent=2)+'\n')
